<template>
<div :class="['ali-host',{'is-awake':awake}]">
 <button type="button" class="ali-launcher" @click="openSettings"><i class="fas fa-cog"></i> ALI</button>
 <button type="button" :class="['ali-wake-toggle',{enabled:wakeEnabled || listening}]" role="switch" :aria-checked="wakeEnabled || listening ? 'true' : 'false'" aria-label="Activaci&#243;n por voz de ALI" @click="toggleWake"><span class="ali-switch-track" aria-hidden="true"><span class="ali-switch-thumb"></span></span><span class="ali-switch-copy"><strong><i class="fas fa-microphone" aria-hidden="true"></i> Hola ALI</strong><small>{{ wakeEnabled || listening ? 'ACTIVADA' : 'DESACTIVADA' }}</small></span></button>
 <div v-if="awake" class="ali-goldfish" role="status" aria-label="ALI activa, pececito dorado"><img class="ali-fish-art" :src="talking?'static/images/ali-goldfish-talking.svg?v=motion-20261015':'static/images/ali-goldfish.svg?v=motion-20261015'" alt="ALI, pececito dorado sonriente"><strong>ALI</strong><span>{{talking?'Hablando':busy?'Procesando':'Te escucho'}}</span></div>
 <span class="ali-operation-state" aria-live="polite">{{ stateLabel }}</span>
 <b-modal v-model="open" title="ALI · Asistente de ventas" hide-footer size="lg" modal-class="ali-modal" @hidden="stopVoice" @shown="expandSettings">
  <div class="ali-status" aria-live="polite"><strong class="ali-state-label">{{ stateLabel }}</strong> {{ listening ? 'Escuchando…' : status }}</div>
  <div class="ali-controls"><button type="button" @click="toggleWake">{{ wakeEnabled ? 'Apagar activación por voz' : 'Activar Hola ALI' }}</button><button type="button" :class="['ali-mic',{listening}]" @click="toggleVoice"><i class="fas fa-microphone"></i> {{ listening ? 'Detener' : 'Hablar con ALI' }}</button><button type="button" class="ali-stop-all" @click="emergencyStop()">Detener micrófono</button><label><input type="checkbox" v-model="continuous"> Escucha continua</label><label><input type="checkbox" v-model="readAloud"> Responder con voz</label><label>Voz de ALI<select v-model="voiceChoice" aria-label="Voz de ALI"><option value="browser">Voz del equipo · Sin consumo API</option><option v-for="voice in cloudVoices" :key="voice.id" :value="voice.id">{{ voice.name }}</option></select></label><label>Estilo<select v-model="voiceStyle" aria-label="Estilo de voz"><option value="natural">Natural</option><option value="dulce">Dulce y suave</option><option value="infantil">Infantil de cuento</option><option value="alegre">Alegre y animada</option></select></label><label v-if="voiceChoice==='browser'">Voz del equipo<select v-model="browserVoice"><option value="">Automática</option><option v-for="voice in localVoices" :key="voice.name" :value="voice.name">{{ voice.name }}</option></select></label><button type="button" @click="testVoice()">Probar voz</button></div><small>Voz generada por IA. Usa el saldo de tu cuenta API cuando OpenAI está activado.</small><p v-if="voiceNotice" class="ali-voice-notice" role="status">{{ voiceNotice }}</p>
  <details class="ali-voice-gallery" open><summary>Comparar 13 voces de OpenAI</summary><p>Escucha la misma frase con cada voz y elige tu favorita. Las pruebas usan tu cuenta API. El estilo infantil cambia la interpretación; no corresponde a una edad específica.</p><div class="ali-voice-grid"><article v-for="voice in cloudVoices" :key="voice.id" :class="['ali-voice-card',{'is-selected':voiceChoice===voice.id}]" :data-voice="voice.id"><strong>{{ voice.name }}</strong><small v-if="voiceChoice===voice.id">Elegida para ALI</small><div><button type="button" @click="testVoice(voice.id)" :aria-label="'Escuchar '+voice.name">{{ previewVoice===voice.id && voiceLoading ? 'Preparando…' : (talking && previewVoice===voice.id ? 'Reproduciendo…' : 'Escuchar') }}</button><button type="button" @click="voiceChoice=voice.id" :aria-pressed="voiceChoice===voice.id">{{ voiceChoice===voice.id ? 'Elegida' : 'Elegir' }}</button></div></article></div><button type="button" @click="stopVoice">Detener audio</button></details>
  <form class="ali-command" @submit.prevent="run"><input v-model="command" maxlength="300" placeholder="ALI, busca cámara Dahua" aria-label="Comando para ALI"><button :disabled="busy" type="submit">Enviar</button></form>
  <details class="ali-command-history"><summary>Últimas órdenes</summary><ol><li v-for="(entry,i) in history" :key="i"><span>{{ entry.command }}</span> · {{ entry.result }}</li></ol><small>Historial temporal de esta página. Los números largos se ocultan.</small></details>
  <details><summary>¿Qué le puedo decir a ALI?</summary><p>“Buscar producto por código” → “Dictar número”. Dicta los números y di “Aceptar”. “Frase del día”, “Busca cinta”, “Agrega el resultado uno”, “Pago con Yape”, “Métodos de pago”, “Total”, “ALI pagar”, “Cancelar”, “Explica cámara Dahua”. Con la activación por voz encendida, di “Hola ALI” para comenzar y “Gracias ALI” para terminar. También puedes pulsar Hablar con ALI para una sola orden. Tras dos esperas de 20 segundos sin interacción, ALI se despide y vuelve a esperar Hola ALI.</p></details>
  <div v-if="pending" class="ali-review"><strong>Revisar antes de cobrar</strong><p>{{ pending }}</p><button type="button" :disabled="busy" @click="command='confirmar pago';run()">Confirmar pago</button><button type="button" @click="command='cancelar';run()">Cancelar</button></div>
  <div v-if="results.length" class="ali-results"><div v-for="(item,i) in results" :key="item.IdProducto"><strong>{{ i+1 }}. {{ item.Producto }}</strong><span>S/ {{ Number(item.PrecioContado || 0).toFixed(2) }} · Stock {{ item.stock }}</span><button type="button" :disabled="busy" @click="command='agrega resultado '+(i+1);run()">Agregar</button><button type="button" @click="learn(item)">Aprender</button></div></div>
  <section v-if="product" class="ali-learning"><h4>{{ product.Producto }}</h4><p>{{ product.ProductoDesc || product.ProductoDescCorto || 'Consulta información y confirma las características del modelo.' }}</p><div class="ali-links"><a :href="videoLink" target="_blank" rel="noopener noreferrer">Buscar videos referenciales</a><a :href="referenceLink" target="_blank" rel="noopener noreferrer">Buscar ficha técnica</a></div><label>Pregunta sobre este producto<input v-model="question" maxlength="1500" placeholder="¿Para qué sirve y cómo se instala?"></label><button type="button" :disabled="busy || !config.enabled" @click="ask">{{ busy ? 'Consultando…' : 'Consultar OpenAI' }}</button><p v-if="!config.enabled">Superadmin puede activar OpenAI en Configurar ALI.</p><p class="ali-answer" aria-live="polite">{{ answer }}</p><ul v-if="sources.length"><li v-for="source in sources" :key="source.url"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }}</a></li></ul><small>Información generada por IA: confirma el modelo y sus características con las fuentes.</small></section>
  <details v-if="config.superadmin" ref="configPanel" class="ali-config"><summary>Configurar ALI · OpenAI</summary><div class="ali-config-state" aria-live="polite"><strong>{{ config.configured ? 'Clave guardada en el servidor' : 'Sin clave guardada' }}</strong><span>{{ config.enabled ? 'IA activada' : 'IA desactivada' }} · {{ config.model }}</span><small v-if="config.savedAt">Último guardado: {{ config.savedAt }}</small></div><p>Introduce tu clave API de OpenAI. Se guarda en el servidor y no vuelve a mostrarse. Las consultas usan el saldo de tu cuenta API.</p><label>Clave API<input v-model="key" type="password" autocomplete="new-password" placeholder="Nueva clave; dejar vacío para conservar"></label><label>Modelo<input v-model="config.model" maxlength="80"></label><label><input type="checkbox" v-model="config.enabled"> Activar consultas con IA</label><label><input type="checkbox" v-model="config.web"> Buscar en internet y citar fuentes</label><p>Se envían a OpenAI el nombre, modelo, descripción del producto y tu pregunta.</p><button type="button" :disabled="busy" @click="saveConfig(false)">{{ busy ? 'Guardando…' : 'Guardar configuración' }}</button><button type="button" :disabled="busy || !config.configured" @click="saveConfig(true)">Desconectar clave</button><p v-if="configMessage" :class="['ali-config-feedback',{'is-error':configError}]" role="status" aria-live="polite">{{ configMessage }}</p></details>
 </b-modal>
</div>
</template>
<script>
import {parseAliCommand,parseAliWake} from '@/utils/aliCommands';
import {aliGreeting,aliEncouragement,aliFarewell} from '@/utils/aliCourtesy';
export default {props:{execute:{type:Function,required:true},warehouse:{type:Number,default:0}},data(){return {open:false,continuous:true,history:[],operationState:'disabled',wakeEnabled:false,awake:false,talking:false,voiceLoading:false,micState:'off',lastHeard:'',configRequested:false,listening:false,command:'',salesOnly:false,activeField:'',barcodeBuffer:'',status:'Di ALI ventas para codigo de barras, ALI clientes para DNI/RUC o ALIPAGO para revisar el pago.',readAloud:true,voiceChoice:'browser',voiceStyle:'infantil',previewVoice:'',cloudVoices:[{'id': 'alloy', 'name': 'Alloy'}, {'id': 'ash', 'name': 'Ash'}, {'id': 'ballad', 'name': 'Ballad'}, {'id': 'coral', 'name': 'Coral'}, {'id': 'echo', 'name': 'Echo'}, {'id': 'fable', 'name': 'Fable'}, {'id': 'nova', 'name': 'Nova'}, {'id': 'onyx', 'name': 'Onyx'}, {'id': 'sage', 'name': 'Sage'}, {'id': 'shimmer', 'name': 'Shimmer'}, {'id': 'verse', 'name': 'Verse'}, {'id': 'marin', 'name': 'Marin'}, {'id': 'cedar', 'name': 'Cedar'}],browserVoice:'',localVoices:[],voiceNotice:'',busy:false,results:[],pending:'',product:null,question:'',answer:'',sources:[],key:'',configMessage:'',configError:false,config:{user:'',enabled:false,configured:false,model:'gpt-4.1-mini',web:true,superadmin:false,csrf:''}}},computed:{stateLabel(){if(this.operationState==='error')return 'Error';if(this.pending)return 'Esperando confirmación';if(this.busy)return this.operationState==='executing'?'Ejecutando':'Procesando';if(this.talking)return 'Respondiendo';if(this.listening)return 'Escuchando';if(this.wakeEnabled)return 'Esperando Hola ALI';return 'Desactivado'},videoLink(){return 'https://www.youtube.com/results?search_query='+encodeURIComponent((this.product.Producto||'')+' '+(this.product.ProductoModelo||'')+' tutorial')},referenceLink(){return 'https://www.google.com/search?q='+encodeURIComponent((this.product.Producto||'')+' '+(this.product.ProductoModelo||'')+' fabricante ficha técnica')}},watch:{continuous(){this.savePreferences();if(this.wakeEnabled||this.listening)this.emergencyStop()},voiceStyle(){this.voicePreferenceChanged()},voiceChoice(){this.voicePreferenceChanged()},browserVoice(){this.savePreferences()},readAloud(){this.savePreferences();if(!this.readAloud){this.cancelAudio();this._speaking=false;this.talking=false;this.scheduleWake()}}},mounted(){this.loadPreferences();document.addEventListener('focusin',this.trackField);document.addEventListener('pointerdown',this.noteInteraction,true);document.addEventListener('input',this.noteInteraction,true);document.addEventListener('keydown',this.noteInteraction,true);this.refreshVoices();if(window.speechSynthesis&&window.speechSynthesis.addEventListener)window.speechSynthesis.addEventListener('voiceschanged',this.refreshVoices);this.loadConfig();this.$root.$on('ali:product-reading',this.onProductReading);this.$root.$on('ali:learn',this.learn);this.$root.$on('ali:open',this.openSettings)},beforeDestroy(){clearTimeout(this._customerLookupTimer);clearTimeout(this._idleTimer);document.removeEventListener('pointerdown',this.noteInteraction,true);document.removeEventListener('input',this.noteInteraction,true);document.removeEventListener('keydown',this.noteInteraction,true);document.removeEventListener('focusin',this.trackField);if(window.speechSynthesis&&window.speechSynthesis.removeEventListener)window.speechSynthesis.removeEventListener('voiceschanged',this.refreshVoices);this.stopWake();this.stopVoice();this.$root.$off('ali:product-reading',this.onProductReading);this.$root.$off('ali:learn',this.learn);this.$root.$off('ali:open',this.openSettings);clearTimeout(this._openTimer)},methods:{onProductReading(active){this._productReading=active;if(active){clearTimeout(this._idleTimer);this.stopWake();this.stopVoice();this.operationState='disabled';this.status='Lectura de ficha en curso. Puedes activar el micrófono al terminar.'}},
 loadPreferences(){try{const value=JSON.parse(localStorage.getItem('aliVoicePreferences')||'{}');if(value.voice==='browser'||this.cloudVoices.some(v=>v.id===value.voice))this.voiceChoice=value.voice;if(['natural','dulce','infantil','alegre'].includes(value.style))this.voiceStyle=value.style;if(typeof value.browserVoice==='string')this.browserVoice=value.browserVoice;if(typeof value.continuous==='boolean')this.continuous=value.continuous;if(typeof value.readAloud==='boolean')this.readAloud=value.readAloud;}catch(e){}},
 savePreferences(){try{localStorage.setItem('aliVoicePreferences',JSON.stringify({voice:this.voiceChoice,style:this.voiceStyle,browserVoice:this.browserVoice,readAloud:this.readAloud,continuous:this.continuous}))}catch(e){}},
 testVoice(voice=this.voiceChoice){this._voiceRetryAt=0;this.say('Hola, soy ALI. Te escucho. ¿Qué producto buscamos hoy?',voice,true);this.previewVoice=voice},
 voicePreferenceChanged(){this._voiceRetryAt=0;this.savePreferences();this.cancelAudio();this._speaking=false;this.talking=false;this.voiceNotice='';this.scheduleWake()},
 armVoiceDeadline(job,text){clearTimeout(this._speechTimer);this._speechTimer=setTimeout(()=>{if(job!==this._voiceJob)return;this.cancelAudio();this._speaking=false;this.talking=false;this.voiceNotice='La reproducción de voz se detuvo. El micrófono vuelve a escuchar.';this.scheduleWake()},Math.min(90000,Math.max(15000,text.length*90+30000)))},
 emergencyStop(message='Micrófono desactivado. Pulsa Activar para volver a escuchar.'){
  this._runVersion=(this._runVersion||0)+1;this._dictationQueue=[];this.pending='';this.activeField='';this.barcodeBuffer='';this.busy=false;this.stopWake();this.stopVoice();this.operationState='disabled';this.status=message;this.execute({type:'cancelSearch'}).catch(()=>{});this.execute({type:'cancel'}).catch(()=>{});
 },
 recordCommand(command,result){const clean=v=>String(v||'').replace(/\b\d{6,}\b/g,'••••').slice(0,150);this.history.unshift({command:parseAliCommand(command).type==='customer'?'Seleccionar cliente (documento oculto)':clean(command),result:clean(result)});this.history=this.history.slice(0,10)},
 async authorize(action){if(!this.config.csrf)await this.loadConfig();return this.request('autorizar',{action:action.type,warehouse:this.warehouse})},
 noteInteraction(event){if(event.type==='input'&&(event.target.id==='txtBarcode'||event.target.dataset.aliCustomer==='true')){this.trackField(event);if(event.target.dataset.aliCustomer==='true')this.scheduleCustomerLookup(event.target.value);}if(this.awake&&event.isTrusted)this.armIdle(true)},
 armIdle(reset=false){clearTimeout(this._idleTimer);this._idleTimer=null;if(reset)this._idleMisses=0;if(!this.awake)return;this._idleTimer=setTimeout(()=>{this._idleTimer=null;this.onIdle()},20000)},
 onIdle(){if(!this.awake)return;if(this.busy||this._speaking){this.armIdle();return}this._idleMisses=(this._idleMisses||0)+1;if(this._idleMisses<2){this.armIdle();return}this.sleepAli('')},
 sleepAli(message){clearTimeout(this._idleTimer);this._idleMisses=0;this.awake=false;this._dictationQueue=[];this.activeField='';this.barcodeBuffer='';this.pending='';this.command='';this.execute({type:'cancel'}).catch(()=>{});this.open=false;this.say(message)},
 scheduleCustomerLookup(number){clearTimeout(this._customerLookupTimer);number=String(number||'').trim();if(this.activeField!=='customer'||!/^\d{8}(?:\d{3})?$/.test(number)||this._customerLookupValue===number)return;const check=()=>{const field=document.querySelector('input[data-ali-customer=true]:focus')||Array.from(document.querySelectorAll('input[data-ali-customer=true]')).find(el=>el.offsetParent!==null);if(this.activeField!=='customer'||!field||field.value.trim()!==number)return;if(this.busy){this._customerLookupTimer=setTimeout(check,150);return}this._customerLookupValue=number;this.command='buscar';this.run()};this._customerLookupTimer=setTimeout(check,number.length===8?600:200)},
 trackField(event){if(event.target.id==='txtBarcode'){this.activeField='barcode';this.barcodeBuffer=event.target.value||''}else if(event.target.dataset.aliCustomer==='true'){this.activeField='customer';this.barcodeBuffer=event.target.value||''}else if(event.target.id==='txtAddProduct'){this.activeField='search';this.barcodeBuffer=''}},
 refreshVoices(){this.localVoices=window.speechSynthesis&&window.speechSynthesis.getVoices?window.speechSynthesis.getVoices().filter(v=>/^es(?:-|_)/i.test(v.lang)):[]},
 openSettings(){this.configRequested=true;this._openTimer=setTimeout(()=>{this.open=true;this.expandSettings()},350)},
 expandSettings(){if(this.configRequested&&this.$refs.configPanel){this.$refs.configPanel.open=true;this.configRequested=false }},
 async request(path,body){let response;try{response=await fetch('/api/index.php/ali/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.config.csrf},body:body?JSON.stringify(body):undefined})}catch(e){throw new Error('Sin conexión con el ERP. Revisa la red y vuelve a intentar.')}const data=await response.json();if(!response.ok){const error=new Error(data.error||'No se pudo completar la solicitud.');if(response.status===401||response.status===403){error.auth=true;this.emergencyStop(error.message)}throw error}return data},
 async loadConfig(){try{this.config=await this.request('config')}catch(e){this.status=e.message;this.operationState='error'}},
 say(text,voiceChoice=this.voiceChoice,preview=false){if(this._productReading)return;clearTimeout(this._idleTimer);this._idleTimer=null;this.previewVoice='';this.pauseWake();if(this._recognition){const speech=this._recognition;this._recognition=null;speech.onend=null;speech.onresult=null;speech.abort();this.listening=false}this.status=text;this.cancelAudio();const job=this._voiceJob;if(voiceChoice!=='browser'&&Date.now()<(this._voiceRetryAt||0)){this._speaking=false;this.talking=false;this.scheduleWake();return}this.voiceNotice='';if(!this.readAloud&&!preview){this._speaking=false;this.talking=false;this.scheduleWake();return}this._speaking=true;this.talking=true;this.armVoiceDeadline(job,text);if(voiceChoice==='browser')this.speakBrowser(text,job);else if(this.config.enabled&&this.config.configured){this._speaking=false;this.talking=false;this.voiceLoading=true;this.speakNatural(text,job,voiceChoice,this.voiceStyle);this.scheduleWake()}else{this._speaking=false;this.talking=false;this.voiceNotice='La voz natural necesita OpenAI activado y saldo API. Puedes elegir una voz del equipo.';this.scheduleWake()}},
 cancelAudio(){this.voiceLoading=false;clearTimeout(this._speechTimer);this._voiceJob=(this._voiceJob||0)+1;if(this._voiceAbort){this._voiceAbort.abort();this._voiceAbort=null}if(this._audio){this._audio.onended=null;this._audio.onerror=null;this._audio.pause();this._audio=null}if(this._audioUrl){URL.revokeObjectURL(this._audioUrl);this._audioUrl=null}this._aliUtterance=null;if(window.speechSynthesis)window.speechSynthesis.cancel()},
 async speakNatural(text,job,voiceChoice=this.voiceChoice,style=this.voiceStyle){let deadline;try{
 const cacheKey=voiceChoice+':'+style+':'+text.slice(0,800);this._voiceCache=this._voiceCache||new Map();let blob=this._voiceCache.get(cacheKey);
 if(!blob){const abort=new AbortController();this._voiceAbort=abort;deadline=setTimeout(()=>abort.abort(),8000);
 const response=await fetch('/api/index.php/ali/voz',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.config.csrf},body:JSON.stringify({text:text.slice(0,800),voice:voiceChoice,style}),signal:abort.signal});
 if(!response.ok){const data=await response.json();throw new Error(data.error||'No se pudo generar la voz.')}blob=await response.blob();clearTimeout(deadline);
 if(this._voiceCache.size>=20)this._voiceCache.delete(this._voiceCache.keys().next().value);this._voiceCache.set(cacheKey,blob);}
 if(job!==this._voiceJob)return;this.voiceLoading=false;this.pauseWake();this._speaking=true;this.talking=true;this._voiceRetryAt=0;this._audioUrl=URL.createObjectURL(blob);const audio=new Audio(this._audioUrl);this._audio=audio;
 audio.onended=()=>{if(job!==this._voiceJob)return;this.cancelAudio();this._speaking=false;this.talking=false;this.scheduleWake()};
 audio.onerror=()=>{if(job!==this._voiceJob)return;this.cancelAudio();this._speaking=false;this.talking=false;this.voiceNotice='No se pudo reproducir el audio. Pulsa Probar voz para habilitarlo.';this.scheduleWake()};await audio.play();
 }catch(e){if(job!==this._voiceJob)return;this.voiceLoading=false;this._voiceRetryAt=Date.now()+60000;this.voiceNotice=e.name==='AbortError'?'OpenAI tardó en responder. Puedes seguir dando órdenes o pulsar Probar voz.':e.message;this._speaking=false;this.talking=false;this.scheduleWake()}finally{clearTimeout(deadline)}},
 speakBrowser(text,job){if(!window.speechSynthesis){this._speaking=false;this.talking=false;this.scheduleWake();return}const voice=new SpeechSynthesisUtterance(text);voice.lang='es-PE';const available=window.speechSynthesis.getVoices?window.speechSynthesis.getVoices():[];const spanish=available.filter(v=>/^es(?:-|_)/i.test(v.lang));const selected=spanish.find(v=>v.name===this.browserVoice)||spanish.find(v=>/sabina|helena|paulina|monica|mónica|laura|elvira|dalia|catalina|female|femenina/i.test(v.name))||spanish[0];if(selected){voice.voice=selected;voice.lang=selected.lang}voice.pitch=({natural:1,dulce:1.1,infantil:1.3,alegre:1.15})[this.voiceStyle]||1;voice.rate=this.voiceStyle==='alegre'?1.08:1;voice.volume=1;this._aliUtterance=voice;voice.onend=()=>{if(job!==this._voiceJob||this._aliUtterance!==voice)return;clearTimeout(this._speechTimer);this._aliUtterance=null;this._speaking=false;this.talking=false;this.scheduleWake()};voice.onerror=voice.onend;window.speechSynthesis.speak(voice)},
 pauseWake(){clearTimeout(this._wakeTimer);if(this._wakeRecognition){const speech=this._wakeRecognition;this._wakeRecognition=null;speech.onend=null;speech.onresult=null;speech.onerror=null;speech.abort()}this.listening=false},
 stopWake(){clearTimeout(this._idleTimer);this._idleTimer=null;this.wakeEnabled=false;this.awake=false;this.micState='off';this.pauseWake()},
 toggleWake(){if(this.wakeEnabled||this.listening){this.emergencyStop();return}this.operationState='listening';if(!this.continuous){this.awake=true;this.toggleVoice();return}const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){this.say('Este navegador no permite activación por voz. Puedes escribir las órdenes.');return}this.stopVoice();this.wakeEnabled=true;this.awake=false;this._wakeFailures=0;this.lastHeard='';this.status='Micrófono en espera. Di Hola ALI para activar y Gracias ALI para terminar.';this.startWake()},
 scheduleWake(){if(!this._idleTimer)this.armIdle();clearTimeout(this._wakeTimer);if(this.wakeEnabled&&!this._speaking){this.micState='restarting';this._wakeTimer=setTimeout(()=>this.startWake(),150)}},
 startWake(){if(!this.wakeEnabled||this._wakeRecognition||this._speaking)return;const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){this.stopWake();return}const speech=new API();this._wakeRecognition=speech;this.micState='starting';speech.lang='es-PE';speech.continuous=true;speech.interimResults=true;
 speech.onstart=()=>{if(this._wakeRecognition===speech){this.listening=this.awake;this.micState=this.awake?'listening':'waiting'}};
 speech.onresult=e=>{if(this._wakeRecognition!==speech)return;this._wakeFailures=0;for(let i=e.resultIndex||0;i<e.results.length;i++){const row=e.results[i],raw=row[0].transcript;this.lastHeard=raw;if(!this.awake){this.handleWakeText(raw);if(row.isFinal!==false){this._wakeFragment=raw;this._wakeFragmentAt=Date.now()}}else if(row.isFinal!==false)this.handleWakeText(raw);if(this._wakeRecognition!==speech)break}};
 speech.onend=()=>{if(this._wakeRecognition!==speech)return;this._wakeRecognition=null;this.listening=false;this.scheduleWake()};
