 if(wake.wake){this.awake=true;this.micState='listening';this._wakeFragment='';const command=wake.command||'Hola ALI';if(this.busy){if(!['pay','confirm'].includes(parseAliCommand(command).type)){this._dictationQueue=this._dictationQueue||[];if(this._dictationQueue.length<10&&this._dictationQueue[this._dictationQueue.length-1]!==command)this._dictationQueue.push(command)}return}this.command=command;this.run();return}
 if(!this.awake)return;this.armIdle(true);if(this.voiceLoading){this.cancelAudio();this._speaking=false;this.talking=false}if(this.busy){if(['pay','confirm'].includes(parseAliCommand(raw).type))return;if(this._activeAction==='search'&&parseAliCommand(raw,{field:this.activeField}).type==='search'){this._runVersion=(this._runVersion||0)+1;this.busy=false;this._dictationQueue=[];this.execute({type:'cancelSearch'}).catch(()=>{});this.command=raw;this.run();return}this._dictationQueue=this._dictationQueue||[];if(this._dictationQueue.length<10)this._dictationQueue.push(raw);return}this.command=raw;this.run()},
