 async run(){
  const entered=this.command;let action=parseAliCommand(entered,{field:this.activeField});if(action.salesOnly||action.reset)this.salesOnly=true;if(action.type==='focus'&&action.field==='customer'&&action.number===undefined){clearTimeout(this._customerLookupTimer);this._customerLookupValue='';}if(this.salesOnly&&((action.type==='focus'&&action.field==='search')||action.type==='search'||action.type==='learn')){this.say('Solo codigo de barras.','browser');return;}
